import java.io.*;import java.util.*;class Node {int val;Node next;Node(int val) {this.val = val;this.next = null;}}public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;int n = Integer.parseInt(line1.trim());if (n == 0) {System.out.println(-1);return;}StringTokenizer st = new StringTokenizer(br.readLine());Node[] nodes = new Node[n];for (int i = 0; i < n; i++) {nodes[i] = new Node(Integer.parseInt(st.nextToken()));}for (int i = 0; i < n - 1; i++) {nodes[i].next = nodes[i + 1];}int pos = Integer.parseInt(br.readLine().trim());if (pos != -1) {nodes[n - 1].next = nodes[pos];}System.out.println(detectCycle(nodes[0]));}public static int detectCycle(Node head) {if (head == null || head.next == null) return -1;Node slow = head;Node fast = head;boolean hasCycle = false;while (fast != null && fast.next != null) {slow = slow.next;fast = fast.next.next;if (slow == fast) {hasCycle = true;break;}}if (!hasCycle) return -1;Node entry = head;int index = 0;while (entry != slow) {entry = entry.next;slow = slow.next;index++;}return index;}}